package main

import (
	"fmt"
	"os"
)

// checkAdd 把断言逻辑抽成纯函数：通过返回 nil，失败返回错误。
// 真实项目里这层交给 *testing.T，这里用纯函数是为了能 go run。
func checkAdd(a, b, want int) error {
	if got := a + b; got != want {
		return fmt.Errorf("add(%d, %d) = %d, want %d", a, b, got, want)
	}
	return nil
}

func main() {
	cases := []struct {
		name string
		a, b int
		want int
	}{
		{"正数", 1, 2, 3},
		{"负数", -1, -2, -3},
		{"零", 0, 0, 0},
	}

	failed := 0
	for _, tc := range cases {
		if err := checkAdd(tc.a, tc.b, tc.want); err != nil {
			fmt.Printf("FAIL %s: %v\n", tc.name, err)
			failed++
			continue
		}
		fmt.Printf("PASS %s\n", tc.name)
	}

	if failed > 0 {
		os.Exit(1)
	}
	fmt.Println("全部通过")
}
